67	export class ConfirmDialogComponent implements AfterViewChecked {
68	  readonly dialogService = inject(DialogService);
69	
70	  @ViewChild('dialogEl') dialogEl?: ElementRef<HTMLElement>;
71	  @ViewChild('cancelBtn') cancelBtn?: ElementRef<HTMLButtonElement>;
72	  @ViewChild('confirmBtn') confirmBtn?: ElementRef<HTMLButtonElement>;
73	
74	  private focusSet = false;
75	
76	  ngAfterViewChecked(): void {
77	    // Auto-focus the cancel button when dialog opens
78	    if (this.dialogService.state().open && !this.focusSet && this.cancelBtn) {
79	      this.cancelBtn.nativeElement.focus();
80	      this.focusSet = true;
81	    }
82	    if (!this.dialogService.state().open) {
83	      this.focusSet = false;
84	    }
85	  }
86	
87	  @HostListener('document:keydown.escape')
88	  onEscape(): void {
89	    if (this.dialogService.state().open) {
90	      this.dialogService.close(false);
91	    }
92	  }
93	
94	  onKeydown(event: KeyboardEvent): void {
95	    if (event.key === 'Tab') {
96	      this.handleTabKey(event);
97	    } else if (event.key === 'Enter') {
98	      // Only trigger confirm if focus is on confirm button
99	      if (document.activeElement === this.confirmBtn?.nativeElement) {
100	        this.dialogService.close(true);
101	      }
102	    }
103	  }
104	
105	  private handleTabKey(event: KeyboardEvent): void {
106	    const focusableElements = [this.cancelBtn?.nativeElement, this.confirmBtn?.nativeElement].filter(Boolean);
107	    const firstElement = focusableElements[0];
108	    const lastElement = focusableElements[focusableElements.length - 1];
109	    const activeElement = document.activeElement;
110	
111	    if (event.shiftKey) {
112	      // Shift + Tab: if on first element, go to last
113	      if (activeElement === firstElement) {
114	        event.preventDefault();
115	        lastElement?.focus();
116	      }
117	    } else {
118	      // Tab: if on last element, go to first
119	      if (activeElement === lastElement) {
120	        event.preventDefault();
121	        firstElement?.focus();
122	      }
123	    }
124	  }
125	
126	  onBackdropClick(event: MouseEvent): void {
127	    if ((event.target as HTMLElement).classList.contains('dialog-backdrop')) {
128	      this.dialogService.close(false);
129	    }
130	  }
131	}
