@use '../../../../styles/variables' as *;
@use '../../../../styles/mixins' as *;

:host {
  display: block;
  min-height: 100vh;
  background: $page;
  color: $ink;
  font-family: $font-family-base;
}

// ============================================
// Container (template root: .dashboard-container)
// ============================================
.dashboard-container {
  @include container;
  padding-block: $space-6;

  @media (max-width: #{$breakpoint-md - 1px}) {
    padding-inline: $container-padding-mobile;
  }

  > h2 {
    @include text-title;
    margin-bottom: $space-6;
    color: $ink;
  }
}

// ============================================
// Tabs
// ============================================
.tabs {
  display: flex;
  gap: $space-2;
  margin-bottom: $space-4;
  border-bottom: 1px solid $line;
  overflow-x: auto;

  button {
    min-height: $ctl-h;
    padding: $space-2 $space-4;
    background: transparent;
    border: 0;
    border-bottom: 2px solid transparent;
    border-radius: $radius-md $radius-md 0 0;
    font-size: $font-size-sm;
    font-weight: $font-weight-semibold;
    color: $ink-2;
    white-space: nowrap;

    &:hover:not(.active):not(:disabled) {
      background: $page;
      border-color: transparent;
      border-bottom-color: transparent;
      color: $ink;
    }

    &.active {
      background: $blue-50;
      border-bottom-color: $blue-600;
      color: $blue-700;
    }
  }
}

// ============================================
// Panel
// ============================================
.panel {
  padding: $space-5;
  background: $surface;
  border: 1px solid $line;
  border-radius: $radius-xl;
  box-shadow: $shadow-card;
  min-width: 0;

  @media (max-width: #{$breakpoint-md - 1px}) {
    padding: $space-4;
  }

  h3 {
    @include text-heading;
    margin: 0 0 $space-4;
    color: $ink;
  }
}

.panel-header-left {
  display: flex;
  align-items: center;
  gap: $space-2;

  h3 {
    margin: 0 0 $space-4;
  }
}

// ============================================
// Filters
// ============================================
.filters {
  display: flex;
  flex-wrap: wrap;
  gap: $space-3;
  align-items: flex-end;
  margin-bottom: $space-4;
  padding: $space-4;
  background: $page;
  border: 1px solid $line;
  border-radius: $radius-md;

  @media (max-width: #{$breakpoint-md - 1px}) {
    flex-direction: column;
    align-items: stretch;

    input,
    select,
    button {
      width: 100%;
    }
  }
}

label {
  display: flex;
  flex-direction: column;
  gap: $space-1;
  font-size: $font-size-sm;
  font-weight: $font-weight-medium;
  color: $ink-2;
}

input,
select {
  min-height: $ctl-h;
  min-width: 140px;
  padding: $space-2 $space-3;
  background: $surface;
  border: 1px solid $line-strong;
  border-radius: $radius-md;
  color: $ink;
  font-size: $font-size-md;
  transition: border-color $transition-base, box-shadow $transition-base;

  &:focus {
    outline: none;
    border-color: $blue-600;
    box-shadow: $focus-ring;
  }

  &::placeholder {
    color: $ink-2;
  }
}

select {
  cursor: pointer;
}

// ============================================
// Buttons (neutral secondary by default)
// ============================================
button {
  min-height: $ctl-h;
  padding: $space-2 $space-4;
  background: $surface;
  border: 1px solid $line-strong;
  border-radius: $radius-md;
  color: $ink;
  font-size: $font-size-sm;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  transition: background $transition-base, border-color $transition-base, color $transition-base;

  &:hover:not(:disabled) {
    background: $page;
    border-color: $ink-2;
  }

  &:focus-visible {
    outline: none;
    box-shadow: $focus-ring;
  }

  &:disabled {
    opacity: 0.55;
    cursor: not-allowed;
  }
}

// Approve buttons in table cells: solid success action
td button {
  min-height: 36px;
  padding: $space-1 $space-4;
  background: $ok;
  border: 1px solid $ok;
  color: #ffffff;
  font-size: $font-size-sm;

  &:hover:not(:disabled) {
    background: darken($ok, 6%);
    border-color: darken($ok, 6%);
  }

  &:disabled {
    background: $page;
    border-color: $line;
    color: $ink-2;
  }

  @media (pointer: coarse) {
    min-height: $ctl-h;
  }
}

// ============================================
// Table (Grid) - scrolls inside the panel, not the viewport
// ============================================
.table-scroll {
  max-width: 100%;
  overflow: auto;
