  border-collapse: separate;
  border-spacing: 0;
  background: $surface;

  th,
  td {
    padding: $space-2 $space-3;
    text-align: left;
    font-size: $font-size-sm;
    border-bottom: 1px solid $line;
    white-space: nowrap;
  }

  th {
    position: sticky;
    top: 0;
    z-index: 1;
    background: $page;
    color: $ink-2;
    font-weight: $font-weight-semibold;
    font-size: $font-size-xs;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  tbody tr:hover {
    background: $blue-50;
  }

  td {
    color: $ink;
  }
}

.grid--wide {
  min-width: 960px;
}

// Status labels (text always present)
.status {
  display: inline-block;
  padding: 2px $space-2;
  border-radius: $radius-full;
  font-size: $font-size-xs;
  font-weight: $font-weight-semibold;
  background: $page;
  color: $ink-2;
  border: 1px solid $line;

  &--ok {
    background: $ok-bg;
    border-color: transparent;
    color: $ok;
  }

  &--warn {
    background: $warn-bg;
    border-color: transparent;
    color: $warn;
  }

  &--info {
    background: $blue-50;
    border-color: transparent;
    color: $blue-700;
  }
}

// ============================================
// Messages
// ============================================
.info,
.muted {
  padding: $space-4;
  text-align: center;
  color: $ink-2;
  font-size: $font-size-sm;
}

.error {
  margin-top: $space-4;
  padding: $space-3 $space-4;
  background: $danger-bg;
  border-left: 3px solid $danger;
  border-radius: $radius-sm;
  color: $danger;
  font-size: $font-size-sm;
}

// ============================================
// Back Link
// ============================================
.back-link {
  display: inline-flex;
  align-items: center;
  min-height: $ctl-h;
  margin-top: $space-4;
  color: $blue-600;
  font-size: $font-size-sm;
  font-weight: $font-weight-medium;
  text-decoration: none;

  &:hover,
  &:focus-visible {
    color: $blue-700;
    text-decoration: underline;
  }
}

