  @media (max-width: #{$breakpoint-md - 1px}) {
    padding: $space-4;
    align-items: flex-start;
  }
}

// ============================================
// Auth Container Block
// ============================================
.auth-container {
  width: 100%;
  max-width: 400px;
  padding: $space-8;
  background: $surface;
  border: 1px solid $line;
  border-radius: $radius-xl;
  box-shadow: $shadow-card;

  @media (max-width: #{$breakpoint-md - 1px}) {
    padding: $space-5;
  }

  h2 {
    @include text-title;
    text-align: center;
    margin-bottom: $space-6;
    color: $ink;
  }
}

// ============================================
// Auth Form Block
// ============================================
.auth-form {
  display: flex;
  flex-direction: column;
  gap: $space-4;

  label {
    display: flex;
    flex-direction: column;
    gap: $space-2;
    font-size: $font-size-sm;
    font-weight: $font-weight-medium;
    color: $ink-2;
  }

  input {
    min-height: $ctl-h;
    padding: $space-2 $space-3;
    background: $surface;
    border: 1px solid $line-strong;
    border-radius: $radius-md;
    color: $ink;
    font-size: $font-size-md;
    transition: border-color $transition-base, box-shadow $transition-base;

    &::placeholder {
      color: $ink-2;
    }

    &:focus {
      outline: none;
      border-color: $blue-600;
      box-shadow: $focus-ring;
    }
  }

  button[type="submit"] {
    margin-top: $space-2;
    min-height: $ctl-h;
    padding: $space-3 $space-4;
    background: $blue-600;
    border: 1px solid transparent;
    border-radius: $radius-md;
    color: #ffffff;
    font-size: $font-size-base;
    font-weight: $font-weight-semibold;
    cursor: pointer;
    transition: background $transition-base, box-shadow $transition-base;

    &:hover:not(:disabled) {
      background: $blue-700;
    }

    &:focus-visible {
      outline: none;
      box-shadow: $focus-ring;
    }

    &:disabled {
      opacity: 0.55;
      cursor: not-allowed;
    }
  }
}

// ============================================
// Messages
// ============================================
.error {
  margin-top: $space-4;
  padding: $space-3;
  background: $danger-bg;
  border-left: 3px solid $danger;
  border-radius: $radius-sm;
  color: $danger;
  font-size: $font-size-sm;
}

// ============================================
// Back Link
// ============================================
.back-link {
  display: inline-flex;
  align-items: center;
  min-height: $ctl-h;
  margin-top: $space-4;
  color: $blue-600;
  font-size: $font-size-sm;
  font-weight: $font-weight-medium;
  text-decoration: none;

  &:hover,
  &:focus-visible {
    color: $blue-700;
    text-decoration: underline;
  }
}

