  for (const c of unexpected.slice(0, 15)) console.log(`CONSOLE ${c.scenario} ${c.type}: ${c.text.slice(0, 160)}`);
  const uniqBlocked = [...new Set(blocked)]; for (const b of uniqBlocked.slice(0, 10)) console.log('BLOCKED', b);
  process.exit(0);
}

